     }

-    private refetchOrder(result: object | undefined): Observable<GetOrderQuery | undefined> {
+    private refetchOrder(result: object | undefined, orderId = this.id): Observable<GetOrderQuery | undefined> {
         this.fetchHistory.next();
         if (result) {
